describe('File Upload - File Name and Size Display', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display file name and size when a file is selected', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        fileId: '12345',
        fileName: 'example.pdf',
        fileSize: '2MB',
        status: 'success'
      }
    }).as('uploadFile');

    // Find the file input and select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify file name and size are displayed
    cy.get('[data-testid="file-name-display"]').should('be.visible');
    cy.get('[data-testid="file-name-display"]').should('contain', 'example.pdf');

    cy.get('[data-testid="file-size-display"]').should('be.visible');
    cy.get('[data-testid="file-size-display"]').should('contain', '2MB');

    // Verify file upload API was called
    cy.wait('@uploadFile');
  });

  it('should handle empty file selection and display appropriate message', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        fileId: '67890',
        fileName: 'empty.txt',
        fileSize: '0B',
        status: 'error'
      }
    }).as('uploadFile');

    // Find the file input and clear it
    cy.get('[data-testid="file-input"]').clear();

    // Verify file name and size are not displayed
    cy.get('[data-testid="file-name-display"]').should('not.exist');
    cy.get('[data-testid="file-size-display"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="file-upload-error-message"]').should('be.visible');
    cy.get('[data-testid="file-upload-error-message"]').should('contain', 'Please select a file');

    // Verify file upload API was not called
    cy.wait('@uploadFile').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });
  });
});
